class HisIntegridadficheros extends BaseHisIntegridadficheros
{

    public static function cargarHistorial($pagina = 1, $limite = 25)
    {

        $pager = new Doctrine_Pager(
            Doctrine_Query:: create()
                ->from('HisIntegridadFicheros h')
                ->orderby( 'h.ultimoescaneo DESC , h.fechaanalisis DESC' ),
            $pagina, // Current page of request
            $limite // (Optional) Number of results per page. Default is 25
        );

        return array('datos' => $pager->execute(), 'total' => $pager->getNumResults() );
    }


}